import json, math, glob, os
import numpy as np
import pandas as pd
import yaml
import statsmodels.api as sm
from scipy import stats

DATA = '/app/data.csv'
OUT = '/app/universes.jsonl'


def _num(v):
    if v is None or not np.isfinite(v):
        return None
    return float(v)


def _direction(v):
    if v is None or not np.isfinite(v) or abs(v) < 1e-15:
        return 'none'
    return 'positive' if v > 0 else 'negative'


def _empty(n=0):
    return {'estimate': None, 'estimate_standardized': None,
            'std_error': None, 'std_error_standardized': None,
            'ci_low_standardized': None, 'ci_high_standardized': None,
            'p_value': None, 'n': int(n), 'direction': 'none',
            'converged': False}


def _binary_series(s):
    if pd.api.types.is_bool_dtype(s):
        return s.astype(float)
    return pd.to_numeric(s, errors='coerce')


def analyze(df, selections: dict[str, str]) -> dict:
    """Run the analysis for ONE universe."""
    try:
        race_choice = selections['race_variable_definition']
        scope = selections['stop_scope']
        outcome_choice = selections['search_outcome_definition']
        missing = selections['missing_search_handling']
        adjustment = selections['confounding_adjustment']
        dependence = selections['uncertainty_dependence']

        d = df.copy()
        if scope == 'durham_county_only':
            d = d[d['county_name'].eq('Durham County')].copy()
        elif scope == 'durham_police_only':
            d = d[d['department_name'].eq('Durham Police Department')].copy()
        elif scope != 'all_dataset_rows':
            raise ValueError('unknown stop scope')

        if race_choice == 'subject_race_black_white':
            r = d['subject_race'].astype('string')
            keep = r.isin(['black', 'white'])
            d = d.loc[keep].copy()
            d['_black'] = r.loc[keep].eq('black').astype(float).to_numpy()
        elif race_choice == 'raw_race_black_white':
            r = d['raw_Race'].astype('string')
            keep = r.isin(['B', 'W'])
            d = d.loc[keep].copy()
            d['_black'] = r.loc[keep].eq('B').astype(float).to_numpy()
        elif race_choice == 'subject_race_with_unknown_as_white':
            r = d['subject_race'].astype('string')
            keep = r.notna()
            d = d.loc[keep].copy()
            d['_black'] = r.loc[keep].eq('black').astype(float).to_numpy()
        else:
            raise ValueError('unknown race definition')

        if outcome_choice == 'search_conducted':
            y = _binary_series(d['search_conducted'])
        elif outcome_choice == 'any_person_or_vehicle_search':
            a, b = _binary_series(d['search_person']), _binary_series(d['search_vehicle'])
            y = pd.Series(np.where(a.notna() & b.notna(), ((a == 1) | (b == 1)).astype(float), np.nan), index=d.index)
        elif outcome_choice == 'person_search_only':
            y = _binary_series(d['search_person'])
        elif outcome_choice == 'vehicle_search_only':
            y = _binary_series(d['search_vehicle'])
        else:
            raise ValueError('unknown outcome definition')
        d['_y'] = y
        if missing == 'missing_as_no_search':
            d['_y'] = d['_y'].fillna(0.0)
        elif missing in ('complete_case', 'report_missing_as_separate_status'):
            d = d[d['_y'].notna()].copy()
        else:
            raise ValueError('unknown missing handling')

        if len(d) < 2 or d['_black'].nunique() < 2 or d['_y'].nunique() < 2:
            return _empty(len(d))

        # Adjustment models require complete covariates; this is a model-fitting
        # requirement, not a universe-specific exception.
        if adjustment == 'unadjusted_rate_comparison':
            n = len(d)
            x = d['_black'].to_numpy(float)
            yy = d['_y'].to_numpy(float)
            nb, nw = int(x.sum()), int((1-x).sum())
            pb, pw = yy[x == 1].mean(), yy[x == 0].mean()
            est = float(pb - pw)
            if dependence == 'iid_two_proportion':
                se = math.sqrt(pb*(1-pb)/nb + pw*(1-pw)/nw)
                pval = 2 * stats.norm.sf(abs(est/se)) if se > 0 else (0.0 if est else 1.0)
            else:
                X = sm.add_constant(x)
                fit = sm.OLS(yy, X).fit()
                if dependence == 'officer_cluster_robust':
                    groups = d['officer_id_hash'].fillna('__missing__')
                elif dependence == 'department_cluster_robust':
                    groups = d['department_name'].fillna('__missing__')
                else:
                    raise ValueError('unknown dependence')
                rob = fit.get_robustcov_results(cov_type='cluster', groups=groups)
                se, pval = float(rob.bse[1]), float(rob.pvalues[1])
            sx = float(np.std(x, ddof=1)); sy = float(np.std(yy, ddof=1))
            scale = sx / sy if sy > 0 else sx
            eststd, sestd = est*scale, se*abs(scale)
            lo, hi = eststd - 1.96*sestd, eststd + 1.96*sestd
            return {'estimate': _num(est), 'estimate_standardized': _num(eststd),
                    'std_error': _num(se), 'std_error_standardized': _num(sestd),
                    'ci_low_standardized': _num(lo), 'ci_high_standardized': _num(hi),
                    'p_value': _num(pval), 'n': n, 'direction': _direction(eststd), 'converged': True}

        if adjustment != 'covariate_adjusted_logistic':
            raise ValueError('unknown adjustment')
        d = d.copy()
        d['_year'] = pd.to_datetime(d['date'], errors='coerce').dt.year
        covars = ['_y', '_black', 'subject_age', 'subject_sex', 'reason_for_stop',
                  'department_name', 'county_name', '_year']
        d = d.dropna(subset=covars).copy()
        if len(d) < 2 or d['_black'].nunique() < 2 or d['_y'].nunique() < 2:
            return _empty(len(d))
        sx = float(d['_black'].std(ddof=1))
        if not np.isfinite(sx) or sx == 0:
            return _empty(len(d))
        d['_black_std'] = (d['_black'] - d['_black'].mean()) / sx
        formula = '_y ~ _black_std + subject_age + C(subject_sex) + C(reason_for_stop) + C(department_name) + C(county_name) + C(_year)'
        model = sm.GLM.from_formula(formula, data=d, family=sm.families.Binomial())
        fit = model.fit()
        if dependence == 'officer_cluster_robust':
            groups = d['officer_id_hash'].fillna('__missing__')
            fit = model.fit(cov_type='cluster', cov_kwds={'groups': groups})
        elif dependence == 'department_cluster_robust':
            groups = d['department_name'].fillna('__missing__')
            fit = model.fit(cov_type='cluster', cov_kwds={'groups': groups})
        elif dependence != 'iid_two_proportion':
            raise ValueError('unknown dependence')
        term = '_black_std'
        eststd = float(fit.params[term]); sestd = float(fit.bse[term])
        est = eststd / sx; se = sestd / sx
        pval = float(fit.pvalues[term])
        lo, hi = eststd - 1.96*sestd, eststd + 1.96*sestd
        return {'estimate': _num(est), 'estimate_standardized': _num(eststd),
                'std_error': _num(se), 'std_error_standardized': _num(sestd),
                'ci_low_standardized': _num(lo), 'ci_high_standardized': _num(hi),
                'p_value': _num(pval), 'n': int(len(d)), 'direction': _direction(eststd),
                'converged': bool(getattr(fit, 'converged', True))}
    except Exception:
        return _empty(0)


def _load_universe(path):
    with open(path) as f:
        u = yaml.safe_load(f)
    decisions = {z['decision_id']: z['option_id'] for z in u['decisions']}
    return u['id'], decisions


def main():
    df = pd.read_csv(DATA, low_memory=False)
    paths = sorted(glob.glob('/app/universes/*.yaml'))
    rows = []
    for path in paths:
        uid, decisions = _load_universe(path)
        result = analyze(df, decisions)
        rows.append({'universe_id': uid, 'decisions': decisions, **result})
    with open(OUT, 'w') as f:
        for row in rows:
            f.write(json.dumps(row, allow_nan=False) + '\n')
    good = [r for r in rows if r['converged'] and r['estimate_standardized'] is not None]
    lines = ['# Multiverse analysis report', '',
             'The analysis compares Black and White search rates. Race, stop scope, search outcome, missing-value handling, adjustment, and uncertainty dependence are all selected from each universe YAML and passed through the same `analyze` function.', '']
    lines += ['## Results', f'- Universes evaluated: **{len(rows)}**', f'- Successful fits: **{len(good)}**']
    if good:
        vals = np.array([r['estimate_standardized'] for r in good])
        lines += [f'- Standardized estimate range: **{vals.min():.6g}** to **{vals.max():.6g}**', f'- Positive estimates: **{sum(v > 0 for v in vals)} / {len(vals)}**', '']
        for dec in sorted({k for r in rows for k in r['decisions']}):
            groups = {}
            for r in good:
                opt = r['decisions'][dec]
                groups.setdefault(opt, []).append(r['estimate_standardized'])
            lines.append(f'### {dec}')
            for opt, a in sorted(groups.items()):
                lines.append(f'- `{opt}`: mean {np.mean(a):.6g}, range {np.min(a):.6g} to {np.max(a):.6g}, n={len(a)}')
            lines.append('')
        lines += ['The largest decision effects can be identified by comparing the option means above; these are descriptive specification-curve summaries, not additional hypothesis tests.', '']
    lines += ['## Method details', '- Unadjusted universes use the Black-minus-White difference in stop-level rates.', '- Adjusted universes fit logistic regression with age, sex, stop reason, department, county, and calendar year covariates.', '- IID uncertainty uses analytic/model-based standard errors; officer or department choices use clustered robust covariance.', '- Standardized estimates use a one-SD Black indicator contrast; unadjusted binary outcomes are additionally expressed in outcome-SD units.']
    with open('/app/results.md', 'w') as f:
        f.write('\n'.join(lines) + '\n')
    print(f'wrote {len(rows)} universes; successful={len(good)}')

if __name__ == '__main__':
    main()
